/**
 * Section headings, levels 2 to 4, for a working screen (`design/components/heading.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/heading.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, ViewEncapsulation, input } from '@angular/core'

import { MEMBER_PROVIDERS, SlotOutlet, SlotTemplate, useMember } from '@polymorph/angular'
import styles from '@polymorph/recipes/structure/heading.module.css'

export type HeadingLevel = NonNullable<HeadingProps['level']>

/** Section headings, levels 2 to 4, for a working screen: the inputs it takes, by the React member's prop names. */
export interface HeadingProps {
  /**
   * The heading element's id, which a fragment link (`#id`) and a TableOfContents item name, so
   * an app names a section without an element of its own around it.
   */
  id?: string
  /**
   * 2 renders `<h2>`, 3 `<h3>`, 4 `<h4>`; never 1, because PageHeader owns the page title.
   */
  level?: 2 | 3 | 4
}

/** Section headings, levels 2 to 4, for a working screen. */
@Component({
  selector: 'pm-heading',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS],
  imports: [SlotOutlet, SlotTemplate],
  // prettier-ignore
  template: `<ng-template pmSlot="default" [pmSlotOf]="$"><ng-content /></ng-template>
@switch (e4()) {
@case ('h4') {<h4
[attr.class]="e1()"
[attr.id]="e2()"
[attr.data-level]="e3()"
data-member="heading"
><ng-container [pmSlotOutlet]="'default'" [pmSlotOf]="$" /></h4>}
@case ('h3') {<h3
[attr.class]="e1()"
[attr.id]="e2()"
[attr.data-level]="e3()"
data-member="heading"
><ng-container [pmSlotOutlet]="'default'" [pmSlotOf]="$" /></h3>}
@default {<h2
[attr.class]="e1()"
[attr.id]="e2()"
[attr.data-level]="e3()"
data-member="heading"
><ng-container [pmSlotOutlet]="'default'" [pmSlotOf]="$" /></h2>}
}`,
})
export class Heading {
  /**
   * The heading element's id, which a fragment link (`#id`) and a TableOfContents item name, so
   * an app names a section without an element of its own around it.
   */
  readonly id = input<HeadingProps['id']>(undefined)
  /**
   * 2 renders `<h2>`, 3 `<h3>`, 4 `<h4>`; never 1, because PageHeader owns the page title.
   */
  readonly level = input<Exclude<HeadingProps['level'], undefined>, HeadingProps['level']>(2, {
    transform: (value: HeadingProps['level']) => (value === undefined ? 2 : value),
  })
  protected readonly $ = useMember({
    events: [],
    props: { id: () => this.id(), level: () => this.level() },
  })
  protected readonly $p = this.$.props

  protected e1() {
    return styles.heading
  }

  protected e2() {
    return this.$p.id
  }

  protected e3() {
    return this.$p.level
  }

  protected e4() {
    return this.$p.level === 4 ? 'h4' : this.$p.level === 3 ? 'h3' : 'h2'
  }
}
